 ('MouseControl', 'MovingTheMouse', 'DurationSteps', 'pyautogui.moveTo(900, 700, duration=0.25)',
  'A move of 400 pixels from (500, 500) to (900, 700) made 1 motion event for duration 0 and 0.1, 3 for 0.11, 6 for 0.25 and 21 for 1.0, every one ending at (900, 700).',
  (X(_PRE + "\nwith Desk(wm=False) as d:\n    import pyautogui; pyautogui.PAUSE = 0\n    o = d.observer(geometry='1920x1080+0+0', mode='paint', w=1900, h=1000); res = {}\n    for dur in (0, 0.1, 0.11, 0.25, 1.0):\n        pyautogui.moveTo(500, 500); o.clear(); t = time.perf_counter(); pyautogui.moveTo(900, 700, duration=dur); el = time.perf_counter() - t\n        ev = [e for e in o.events() if e['type'] == 'Motion']; gaps = [ev[i + 1]['t'] - ev[i]['t'] for i in range(len(ev) - 1)]\n        res[dur] = (len(ev), (ev[0]['x_root'], ev[0]['y_root']), (ev[-1]['x_root'], ev[-1]['y_root']), dur <= el < dur + 0.5 if dur > 0.1 else el < 0.05, (0.03 < min(gaps) and max(gaps) < 0.3) if gaps else None)\n    out = res\n"), '{0: (1, (900, 700), (900, 700), True, None), 0.1: (1, (900, 700), (900, 700), True, None), 0.11: (3, (500, 500), (900, 700), True, True), 0.25: (6, (500, 500), (900, 700), True, True), 1.0: (21, (500, 500), (900, 700), True, True)}')),
