 ('ScreenAndImages', 'ImageRecognition', 'LocateWaits', 'minSearchTime=5',
  'locateOnScreen raised ImageNotFoundException at once when the button was not there, and with minSearchTime=5 it kept looking, found the button that appeared 1.2 seconds later at (400, 300, 84, 35) and returned within 4.5 seconds.',
  (X(_PRE + '\nwith Desk(wm=False) as d:\n    import pyautogui; pyautogui.PAUSE = 0\n    cfg = dict(mode=\'button\', geometry=\'400x300+300+200\', buttons=[[100, 100]], log=os.path.join(d.dir, \'l.jsonl\'), state=os.path.join(d.dir, \'s.json\'))\n    o = d.observer(mode=\'button\', geometry=\'400x300+300+200\', buttons=[[100, 100]]); x, y, w, h = o.state()[\'buttons\'][0]; os.chdir(d.dir)\n    pyautogui.screenshot().crop((x, y, x + w, y + h)).save(\'submit.png\'); o.close(); time.sleep(0.5)\n    t = time.perf_counter()\n    try: pyautogui.locateOnScreen(\'submit.png\'); r1 = \'found\'\n    except pyautogui.ImageNotFoundException: r1 = \'ImageNotFoundException\'\n    e1 = time.perf_counter() - t\n    d.start([\'sh\', \'-c\', \'sleep 1.2; exec %s -c "$0" "$1"\' % LATEST, OBSERVER, json.dumps(cfg)], \'late\'); t = time.perf_counter()\n    try: b = pyautogui.locateOnScreen(\'submit.png\', minSearchTime=5); r2 = tuple(int(v) for v in b)\n    except pyautogui.ImageNotFoundException: r2 = \'ImageNotFoundException\'\n    e2 = time.perf_counter() - t\n    out = (r1, e1 < 1.0, r2, (x, y, w, h) == r2 if r2 != \'ImageNotFoundException\' else None, 1.0 <= e2 < 4.5)\n'), "('ImageNotFoundException', True, (400, 300, 84, 35), True, True)")),
